import math

def sim_crop(crop_id, temp_day, temp_night, co2_ppm, par_umol, photo_h, days, init_x=None):
    if crop_id == "broccoli_micro":
        closure = 31.9; dm = 0.093; density = 29000.0; ready_fw = 0.086; init_dw = 0.0012
    else:
        closure = 15.8; dm = 0.07; density = 19000.0; ready_fw = 0.116; init_dw = 0.0025

    X = init_x if init_x is not None else (init_dw * density / 1000.0)
    dt = 300.0 # 5 min
    for d in range(days):
        for h in range(24):
            is_photo = h < photo_h
            T = temp_day if is_photo else temp_night
            par = par_umol if is_photo else 0.0
            co2 = co2_ppm if is_photo else 420.0
            for _ in range(12):
                # cardinal temperature
                if T <= 2.925 or T >= 42.085:
                    tf = 0.0
                else:
                    # standard cardinal or parabolic? let us check standard linear/beta cardinal
                    if T <= 22.505:
                        tf = (T - 2.925) / (22.505 - 2.925)
                    else:
                        tf = (42.085 - T) / (42.085 - 22.505)
                g_car = 0.001959 * tf
                g = 1.0 / (1.0/0.007 + 1.0/0.005 + 1.0/g_car) if g_car > 0 else 0.0
                C = min(co2, 1200.0) * 1.8295e-6
                Gamma = 5.2e-5 * (2.0 ** ((T - 20.0)/10.0))
                eps_I = 1.7e-8 * par * 0.2188
                if eps_I > 0 and g > 0 and C > Gamma:
                    P = (1.0 - math.exp(-closure * X)) * eps_I * g * (C - Gamma) / (eps_I + g * (C - Gamma))
                else:
                    P = 0.0
                resp = 2.65e-7 * X * (2.0 ** ((T - 25.0)/10.0))
                X += (0.544 * P - resp) * dt
        fw = X / dm / density * 1000.0
        if fw >= ready_fw:
            return d + 1, fw, X
    return days, X / dm / density * 1000.0, X

for crop in ["broccoli_micro", "radish_micro"]:
    for par in [200, 250, 300]:
        for co2 in [800, 1000, 1200]:
            for td, tn in [(20, 17), (22, 17), (22, 19)]:
                d, fw, X = sim_crop(crop, td, tn, co2, par, 16, 20)
                dli = par * 16 * 3600 / 1e6
                print(f"{crop:15s} PAR={par} (DLI={dli:.1f}) CO2={co2} T={td}/{tn} -> ready day {d}, fw={fw:.4f}")
'
